def subtract(a, b):
    # Normalize inputs: filter out empty intervals and sort
    a_intervals = sorted([interval for interval in a if interval[0] < interval[1]])
    b_intervals = sorted([interval for interval in b if interval[0] < interval[1]])

    # Merge overlapping intervals in b
    b_merged = []
    for start, end in b_intervals:
        if b_merged and start <= b_merged[-1][1]:
            # Overlapping or touching: merge
            b_merged[-1][1] = max(b_merged[-1][1], end)
        else:
            # Non-overlapping: add new interval
            b_merged.append([start, end])

    # For each interval in a, subtract all b intervals from it
    result = []
    for a_start, a_end in a_intervals:
        current_ranges = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            next_ranges = []
            for c_start, c_end in current_ranges:
                # If no overlap between [c_start, c_end) and [b_start, b_end)
                if c_end <= b_start or c_start >= b_end:
                    # No overlap: keep the range
                    next_ranges.append([c_start, c_end])
                else:
                    # Overlap: split the range
                    if c_start < b_start:
                        next_ranges.append([c_start, b_start])
                    if c_end > b_end:
                        next_ranges.append([b_end, c_end])
            current_ranges = next_ranges

        result.extend(current_ranges)

    # Sort and merge touching intervals
    result.sort()
    merged = []
    for start, end in result:
        if merged and start <= merged[-1][1]:
            # Overlapping or touching: merge
            merged[-1][1] = max(merged[-1][1], end)
        else:
            # Non-overlapping: add new interval
            merged.append([start, end])

    return merged

